using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London'")] string city,
        [Description("Units: 'metric' or 'imperial'")] string units = "metric")
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/weather?q={Uri.EscapeDataString(city)}&units={units}");

        if (response is null)
            return "No weather data available.";

        return $"{response.Name}: {response.Main.Temp}° ({response.Weather.FirstOrDefault()?.Description})";
    }

    [McpServerTool, Description("Get a 5-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city)
    {
        var response = await _httpClient.GetAsync(
            $"/forecast?q={Uri.EscapeDataString(city)}&units=metric");

        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();
        return content;
    }
}

// Response models
public record WeatherResponse(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("main")] MainData Main,
    [property: JsonPropertyName("weather")] List<WeatherDescription> Weather);

public record MainData(
    [property: JsonPropertyName("temp")] double Temp,
    [property: JsonPropertyName("humidity")] int Humidity);

public record WeatherDescription(
    [property: JsonPropertyName("description")] string Description);

